\label{Def:SolidBF}
Let $\mathscr B$ be a
\emph{QBF space} on
$\mathbf R^{d}$.
Then $\mathscr B$ is
called \emph{solid} if the
following conditions hold:
\begin{enumerate}
\item
for any
$f,g\in \mathcal M (\mathbf R^{d})$
which satisfy
$g\in \mathscr B$ and $|f|
\le |g|$, then $f\in \mathscr B$ and

\begin{equation}\label{Eq:Solid}
\Vert f\Vert _{\mathscr B}\le C\Vert g\Vert _{\mathscr B},
\end{equation}

for some constant $C>0$, independent of $f$ and $g$ above;

\vspace{0.1cm}

\item
for any $x\in \mathbf R^{d}$,
there is a constant $c>0$ and a function
$f\in \mathscr B$ such that $|f|>c$ on a non-null convex
set in $\mathbf R^{d}$ containing $x$.
\end{enumerate}
The space space $\mathscr B$ is called \emph{strict solid}
if it is solid and \eqref{Eq:Solid} holds for $C=1$.

\label{Def:ExtendedSchattFamily}
Let $\mathcal B \hookrightarrow \ell ^\infty (\mathbf N)$ be a topological vector space, $T\in \mathscr I _\infty$,
and

\begin{equation}
\label{Eq:OmegaTDef}
\Omega _T =\{ \, \{ (Tf_j,g_j ) _{L^2}\}_{j=0}^\infty \, ;\, \{ f_j\}_{j=0}^\infty , \{ g_j\}_{j=0}^\infty \in \operatorname{ON}\, \} .
\end{equation}

\begin{enumerate}
\item $T$ is called a Schatten-von Neumann
operator of order $\mathcal B$, if $\Omega _T$ is a bounded subset of
$\mathcal B$.









The set of Schatten-von Neumann operators of order $\mathcal B$ is denoted
by $\mathscr I _\mathcal B$.

\vspace{0.1cm}

\item If in addition $\mathcal B$ is a quasi-Banach space with quasi-norm
$\Vert \, \cdot \, \Vert _{\mathcal B}$, then $\mathscr I _\mathcal B$ is equipped with the
topology, defined by the quasi-norm

\begin{equation}
\label{Eq:SchattNorm}
\Vert T\Vert _{\mathscr I _\mathcal B}
\equiv
\sup _{c\in \Omega _T}\Vert c\Vert _{\mathcal B},
\qquad
T\in \mathscr I _\mathcal B .
\end{equation}

\end{enumerate}

Let $\mathcal B \hookrightarrow \ell^\infty (\mathbf N)$ be a topological vector space.
\begin{enumerate}
\item $\mathscr I _\mathcal B$ is a vector space.

\vspace{0.1cm}

\item If in addition $\mathcal B$ is a quasi-Banach space,
then $\mathscr I _\mathcal B$ is a quasi-Banach space of the same
order as $\mathcal B$.
\end{enumerate}

\label{Prop:SchwartzKerWeylOp}
The map

\begin{equation}
\label{Eq:SymbToWeylOp}
\mathfrak a \mapsto \operatorname{Op} ^w(\mathfrak a ).
\end{equation}

is a bijection
from $\mathscr S '(\mathbf R^{2d})$
to $\mathcal L (\mathscr S (\mathbf R^{d}),\mathscr S '(\mathbf R^{d}))$.

Let $\mathcal B \hookrightarrow \ell ^\infty (\mathbf N)$ be a topological vector space.
\begin{enumerate}
\item The map \eqref{Eq:SymbToWeylOp}
is an isomorphism from $s_\mathcal B ^w(\mathbf R^{2d})$
to $\mathscr I _\mathcal B$.

\vspace{0.1cm}

\item If in addition
$\mathcal B$ is a quasi-Banach space, then
the map \eqref{Eq:SymbToWeylOp} is an
isometric bijection from $s_\mathcal B ^w(\mathbf R^{2d})$
to $\mathscr I _\mathcal B$.
\end{enumerate}

\label{Prop:SchatSymbChar}
Let $\mathcal B \hookrightarrow \ell ^\infty (\mathbf N)$ be a topological vector space,
$\mathfrak a \in s_\infty ^w(\mathbf R^{2d})$, and

\begin{equation}
\label{Eq:OmegaaDef}
\Omega _\mathfrak a = \{ \, \{ (\mathfrak a ,W_{f_j,g_j})_{L^2} \} _{j\in \mathbf N}\, ;\, \{ f_j\} _{j\in \mathbf N},\{ g_j\} _{j\in \mathbf N}\in \operatorname{ON}\, \} .
\end{equation}

\begin{enumerate}
\item $\mathfrak a \in s_\mathcal B ^w(\mathbf R^{2d})$, if and only if
$\Omega _\mathfrak a$ is a bounded subset of $\mathcal B$.

\par

\item If, in addition, $\mathcal B$ is a quasi-Banach space,
then

\begin{equation}
\label{Eq:SchattSymbNorm2}
\Vert \mathfrak a\Vert _{s_\mathcal B ^w} = (2\pi )^{-\frac d2}
\sup _{c\in \Omega _{\mathfrak a}}\Vert c\Vert _{\mathcal B},
\end{equation}

where the supremum is taken over all
$\{ f_j\} _{j\in \mathbf N}$ and $\{ g_j\} _{j\in \mathbf N}\in \operatorname{ON}$.
\end{enumerate}

\label{Def:GeneralPartFracSympFT}
Let $\rho ,\theta \in \mathbf R^{d}$,
and let $T_{\rho ,\theta}$ be the map on
$A(\mathbf C^{2d})$, given by

\begin{equation}
\label{eq:DefTrhotheta}
(T_{\rho ,\theta}F)(z,w)=F(A_{\rho ,\theta }(z,w)).
\end{equation}

The partial fractional symplectic Fourier transform
on $\mathscr S '(\mathbf R^{2d})$ of
order $(\rho ,\theta )\in \mathbf R^{2d}$
is the operator

\begin{equation}
\label{Eq:PartFracSymplFTFormula}
\mathscr F _{\sigma ,(\rho ,\theta )}
\equiv
\mathfrak V_{\sigma ,d}^{-1}
\circ
T_{\rho ,\theta}
\circ
\mathfrak V_{\sigma ,d}.
\end{equation}

\label{Lemma:FracFourKernBargIdent}
Let $\rho ,\theta \in \mathbf R^{d}$.
Then the following are true:
\begin{enumerate}
\item
$K_{\rho}$ in \eqref{Eq:FracFourNoPartial}
is given by

\begin{equation}
\label{Eq:FracFourKernBargIdent}
K_{\rho} (x,y)
=
\pi ^{-\frac d2}\int _{\mathbf C^{d}}
\mathfrak A_d(\overline z,x)
\mathfrak A_d(A_\rho ^0 z,y)\, d\mu _d(z),
\quad x,y\in \mathbf R^{d} \text ;
\end{equation}


\vspace{0.1cm}

\item $K_{\sigma ,(\rho ,\sigma )}$
in Definition \ref{Def:KernPartSymplFourT} is given by

\begin{multline}
\label{Eq:FracSymplFourKernBargIdent}
K_{\sigma ,(\rho ,\theta )} (x,\xi ,y,\eta )
\\[1ex]
=
\left (
\frac 2\pi
\right )^{d}
\iint _{\mathbf C^{2d}}
\mathfrak A_{\sigma ,d}
(\overline z,\overline w,x,\xi )
\mathfrak A_{\sigma ,d}
( A_{\rho ,\theta}(z,w),y,\eta )
\, d\mu _{\sigma ,d}(z,w),
\\[1ex]
x,y,\xi ,\eta \in \mathbf R^{d} \text .
\end{multline}

\end{enumerate}

\label{Thm:Main}
Let $\rho ,\theta \in \mathbf R^{d}$.
Then

\begin{align}
\mathscr F _{\sigma ,(\rho ,\theta )} \circ \mathscr W 
&=
\mathscr W \circ \mathscr F _{(-\rho -\theta ,
-\rho +\theta )}
\label{Eq:FracSympActAdv}
\end{align}

as operators on
$\mathscr S '(\mathbf R^{2d})$.

\label{Lemma:BargmannWigner}
Let $f,g\in \mathscr S '(\mathbf R^{d})$
and $F\in \mathscr S '(\mathbf R^{2d})$.
Then

\begin{align}
(\mathfrak V _{\sigma ,d}W_{f,g})(z,w)
&=
2^{-\frac d2}
(\mathfrak V _df)(z-iw)\cdot (\mathfrak V _d\overline g)(z+iw)
\label{Eq:BargmannWigner}
\intertext{and}
(\mathfrak V _{\sigma ,d}(\mathscr W \! F))(z,w)
&=
2^{-\frac d2}
(\mathfrak V _{2d}F)(z-iw,z+iw)
\label{Eq:BargmannWignerAdv}
\end{align}

\label{Prop:FracSymplFourGroupProp}
It holds

\begin{equation}
\begin{aligned}
\mathscr F _{\sigma ,(\rho _1,\theta _1)}\circ \mathscr F _{\sigma ,(\rho _2,\theta _2)}
&= \mathscr F _{\sigma ,(\rho _1+\rho _2,\theta _1+\theta _2)},
\\[1ex]
\mathscr F _{\sigma ,(\rho ,\theta )} ^{-1} &= \mathscr F _{\sigma ,(\rho ,\theta )} ^*
= \mathscr F _{\sigma ,(-\rho ,-\theta )},
\\[1ex]
\mathscr F _{\sigma ,(0,0)} &=\operatorname{Id}_{L^2},
\quad \text{and}\quad
\mathscr F _{\sigma (\rho +\gamma ,\theta +\delta )}=\mathscr F _{\sigma ,(\rho ,\theta )},
\\[1ex]
\rho ,\rho _j,\theta ,\theta _j &\in \mathbf R^{d},\ \gamma ,\delta \in 2\mathbf Z^{d}, j=1,2,
\end{aligned}
\end{equation}

as operators on $\mathscr S '(\mathbf R^{2d})$.

\label{Thm:FracSymplFourSchattInv}
Let $\rho ,\theta \in \mathbf R^{d}$, $\mathcal B \hookrightarrow \ell ^\infty (\mathbf N)$ be a topological vector space, and $\Omega _\mathfrak a$ be as in
\eqref{Eq:OmegaaDef}.
Then the following are true:
\begin{enumerate}
\item $\mathscr F _{\sigma ,(\rho ,\delta )}$ is bijective on $s_{0,N}^w(\mathbf R^{2d})$
for every $N\in \mathbf N$;

\vspace{0.1cm}

\item $\Omega _{\mathscr F_{\sigma ,(\rho ,\theta)}\mathfrak a}=\Omega _{\mathfrak a}$;

\vspace{0.1cm}

\item the map $\mathfrak a \mapsto \mathscr F_{\sigma ,(\rho ,\theta )}\mathfrak a$ on
$\mathscr S '(\mathbf R^{2d})$, restricts to an isomorphism on $s_\mathcal B ^w(\mathbf R^{2d})$;

\vspace{0.1cm}

\item if, in addition, $\mathcal B$ is a quasi-Banach space, then

\begin{equation}
\Vert \mathscr F_{\sigma ,(\rho ,\theta )}\mathfrak a\Vert _{s_\mathcal B ^w}
=
\Vert \mathfrak a\Vert _{s_\mathcal B ^w}.
\end{equation}

\end{enumerate}

\label{Prop:BasicMapsOnGS}
Let $s\ge \frac 12$, $t > \frac12$, and $\rho 
\in \mathbf R^{d}$.

\begin{enumerate}
\item $\mathscr F _\rho$ restricts
to homeomorphisms on $\mathcal S _s (\mathbf R^{d})$,  $\Sigma_t(\mathbf R^{d})$, and $\mathscr S (\mathbf R^{d})$.

\vspace{0.1cm}

\item $\mathscr F _\rho$ is unitary on
$L^2(\mathbf R^{d})$.

\vspace{0.1cm}

\item $\mathscr F _\rho$ extends
uniquely to homeomorphisms on
$\mathcal S _s'(\mathbf R^{d})$, $\Sigma_t'(\mathbf R^{d})$
, and $\mathscr S '(\mathbf R^{d})$.
\end{enumerate}

\label{Def:SeqSpaces1}
Let $p\in (0,\infty ]$, $r\in \mathbf R _+$,
$s\in \mathbf R _{\flat ,\infty}$, $\vartheta$ be a
positive function on $\mathbf N^{d}$, and let

\begin{equation}
\vartheta _{r,s}(\alpha )
\equiv
\begin{cases}
e^{r|\alpha |^{\frac 1{2s}}}, & s\in \mathbf R _+,
\\[1ex]
r^{|\alpha |}\alpha !^{\frac 1{2\sigma}}, & s=\flat _\sigma ,
\\[1ex]
(1+|\alpha |)^r, & s= \infty , 
\end{cases}
\qquad \alpha \in \mathbf N^{d}
\end{equation}

\begin{enumerate}
\item $\ell _{[\vartheta ]}^p(\mathbf N^{d})$ is the quasi-Banach
space which consists of
all $c\in \ell _0'(\mathbf N^{d})$ such that
$$
\Vert c\Vert _{\ell _{[\vartheta ]}^p}
\equiv
\Vert \{ c(\alpha )\vartheta (\alpha )\} _{\alpha \in \mathbf N^{d}}\Vert _{\ell ^p}
$$
is finite.

\vspace{0.1cm}

\item $\ell _{0,s}(\mathbf N^{d})\equiv \bigcap _{r>0}\ell _{[\vartheta _{r,s}]}^p(\mathbf N^{d})$
and $\ell _{s}(\mathbf N^{d})\equiv \bigcup _{r>0}\ell _{[\vartheta _{r,s}]}^p(\mathbf N^{d})$,
with projective and inductive limit topologies, respectively


\vspace{0.1cm}

\item $\ell _{0,s}'(\mathbf N^{d})\equiv \bigcup _{r>0}\ell _{[1/\vartheta _{r,s}]}^p(\mathbf N^{d})$
and $\ell _{s}'(\mathbf N^{d})\equiv \bigcap _{r>0}\ell _{[1/\vartheta _{r,s}]}^p(\mathbf N^{d})$,
with inductive and projective limit topologies, respectively

\end{enumerate}

\label{Def:GenPilSpaces}
Let $\mathcal B \hookrightarrow \ell _0'(\mathbf N^{d})$
and $\mathcal C \hookrightarrow \ell _0'(\mathbf N^{2d})$ be topological
vector spaces.
\begin{enumerate}
\item The \emph{Pilipovi{\'c} space with respect to $\mathcal B$},
or the \emph{$\mathcal B$-Pilipovi{\'c} space},
is given by

\begin{align}
\mathcal H _\mathcal B (\mathbf R^{d})
&\equiv
\{ \, f\in \mathcal H _0'(\mathbf R^{d})\, ;\, \{ c(f;\alpha )\} _{\alpha \in \mathbf N^{d}}\in \mathcal B\, \} ,
\end{align}

with the topology inherited from $\mathcal B$.

\vspace{0.1cm}

\item The \emph{Pilipovi{\'c}-Wigner space with respect to $\mathcal C$},
or the \emph{$\mathcal C$-Pilipovi{\'c}-Wigner space},
is given by

\begin{align}
\mathcal V\! \mathcal H _{\mathcal C} (\mathbf R^{2d})
&\equiv
\{ \, \mathfrak a \in \mathcal V\! \mathcal H _{0}'(\mathbf R^{2d})\, ;\, \{ c_\sigma (\mathfrak a ;\alpha ,\beta )\} _{\alpha ,\beta \in \mathbf N^{d}}\in \mathcal C\, \} ,
\end{align}

with the topology inherited from $\mathcal C$.
\end{enumerate}

\label{Prop:BHBSymplHBRel}
Let $\mathcal B \hookrightarrow \ell _0'(\mathbf N^{2d})$ be
a topological vector space. Then the mappings in
the commutative diagram

\begin{equation}
\label{Eq:BHBSymplHBRel}
\begin{tikzcd}
\mathcal B \arrow[dr , "\mathfrak H _\sigma" '] \arrow[r, "\mathfrak H"] 
& \mathcal H _\mathcal B (\mathbf R^{2d})\arrow[d, "\mathscr W"]
\\
& \mathcal V\! \mathcal H _{\mathcal B} (\mathbf R^{2d})
\end{tikzcd}
\end{equation}

are homeomorphisms.

\label{Rem:FracFourGSSpaces}
Let $\mathcal B$ be as in \eqref{Eq:StandPilSpaces},
when $s_1>\frac 12$ and $s_2\ge \frac 12$.
Then Proposition \ref{Prop:BasicMapsOnGS}
in Section \ref{sec4}
follows by choosing
$\Omega =\mathbf R^{d}$ in Theorem \ref{Thm:FracFourGenPil}.

\par

In the same way it follows that Theorem 
\ref{Thm:MapPartFracSymplFTGS} 
in Section \ref{sec4}
follows by choosing $\Omega =\mathbf R^{d}$ in
Theorem \ref{Thm:FracSymplFourGenPil}.

\label{Prop:SuffCondPartFracSymplFTHomeo2}
Let $\mathcal B \hookrightarrow \ell _0'(\mathbf N^{2d})$ 
be a topological vector space which is 
rotational invariant with respect to $\mathbf R^{2d}$ 
such that
$\ell _0(\mathbf N^{2d})\hookrightarrow \mathcal B$, 
$\mathcal B ' \hookrightarrow \ell_0'(\mathbf N^{2d})$, and 

\begin{equation}
\label{Eq:GenGelfTripleSeq}
(\mathcal B ,\ell ^2(\mathbf N^{2d}),\mathcal B ')
\end{equation}

is a Gelfand triple.                                                     
Also, suppose that the map

\begin{equation}
\label{Eq:WignerDilation2}
F(x,y) \mapsto F(x+\textstyle{\frac y2},x-\textstyle{\frac y2})
\end{equation}

is a homeomorphism on $\mathcal H _\mathcal B (\mathbf R^{2d})$. Then
the following are true:
\begin{enumerate}
\item it holds
$$
\mathcal H _{\mathcal B} (\mathbf R^{2d}) = \mathcal V\! \mathcal H _{\mathcal B} (\mathbf R^{2d})
\quad \text{and}\quad
\mathcal H _{\mathcal B} '(\mathbf R^{2d})
=
\mathcal H _{\mathcal B '} (\mathbf R^{2d})
=
\mathcal V\! \mathcal H _{\mathcal B '} (\mathbf R^{2d});
$$

\vspace{0.1cm}

\item if $\rho ,\theta \in \mathbf R^{d}$, then $\mathscr F _{\sigma ,(\rho ,\theta )}$
on $\mathcal V\! \mathcal H _0'(\mathbf R^{2d})$ restricts to homeomorphisms on
$\mathcal H _{\mathcal B} (\mathbf R^{2d})$ and on $\mathcal H _{\mathcal B '} (\mathbf R^{2d})$.
\end{enumerate}

\label{Rem:GSTriplHomeomorph}
Suppose $\mathcal B \hookrightarrow \ell _0'(\mathbf N^{2d})$ be  a
topological vector space such that
$\ell _0(\mathbf N^{2d})\hookrightarrow \mathcal B$,
$\mathcal B '\hookrightarrow \ell _0'(\mathbf N^{2d})$, and that
\eqref{Eq:GenGelfTripleSeq} is a Gelfand triple. Then
it follows by straight-forward computations
that the mappings \eqref{Eq:BHBSymplHBRel}
induce homeomorphisms of Gelfand triples

\begin{equation}
\label{Eq:BHBSymplHBRelGeShTriple}
\begin{tikzcd}
\big ( \mathcal B ,\ell ^2(\mathbf N^{2d}), \mathcal B ' \big )
\arrow[dr , "\mathfrak H _\sigma" '] \arrow[r, "\mathfrak H"] 
& \big ( \mathcal H _\mathcal B (\mathbf R^{2d}), L^2(\mathbf R^{2d}), \mathcal H _{\mathcal B '} (\mathbf R^{2d}) \big )
\arrow[d, "\mathscr W"]
\\
& \big ( \mathcal V\! \mathcal H _\mathcal B (\mathbf R^{2d}), L^2(\mathbf R^{2d}),
\mathcal V\! \mathcal H _{\mathcal B '} (\mathbf R^{2d}) \big ) .
\end{tikzcd}
\end{equation}

The details are left for the reader.

\label{Def:GenModSpace}
Let $\mathscr B$ be a solid QBF space on $\mathbf R^{2d}$, 
$\omega \in\mathscr P _A(\mathbf R^{2d})$,
and let
$\phi _0$ be as in \eqref{Eq:GaussWindow}. 
Then the \emph{modulation space} $M(\omega ,\mathscr B )$ consists
of all $f\in \mathcal H _{\flat _1}'(\mathbf R^{d})$ such that

\begin{equation}
\label{Eq:GenModNormDef}
\Vert f\Vert _{M(\omega ,\mathscr B )}
\equiv \Vert V_{\phi _0} f\cdot \omega \Vert _{\mathscr B}
\end{equation}

is finite.

\label{Def:FrFTScales}
Let $\mathscr B$ be a solid QBF space on $\mathbf R^{2d}$, and let
$A_{\rho}$ be as in \eqref{Eq:ArhothetaDefB}.
\begin{enumerate}
\item The space $\mathscr B _\rho$ is given by

\begin{equation}
\mathscr B _\rho
\equiv
\{ \, F\in \mathcal M (\mathbf R^{2d})\, ;\, F(A_{\rho }^{-1} \, \cdot \, )\in \mathscr B\, \} .
\end{equation}

The topology of $\mathscr B _\rho$ is given by the
quasi-norm

\begin{equation}
\Vert F\Vert _{\mathscr B _\rho}
\equiv 
\Vert F(A_{\rho}^{-1}\, \cdot \,  )\Vert _{\mathscr B},
\qquad
F\in \mathscr B _\rho .
\end{equation}


\vspace{0.1cm}

\item $\mathscr B$ is called \emph{phase rotational invariant}
if $\mathscr B _\rho =\mathscr B$
and $\Vert F\Vert _{\mathscr B _\rho}=\Vert F\Vert _{\mathscr B}$, for every $\rho \in \mathbf R^{d}$ and
$F\in \mathscr B$.
\end{enumerate}

\label{Lemma:SymplSTFTSymplBarg}
Let

\begin{equation}
\label{Eq:SymplGaussWindow}
\begin{gathered}
\psi _0(X)
=
\left (\frac 2\pi \right )^{\frac d2}
e^{-|X|^2},
\quad
J=\left (
\begin{matrix}
0 & I_{d}
\\
-I _d & 0
\end{matrix}
\right ),
\\[1ex]
\text{and}\quad
\kappa(X,Y)=2^{-1/2}(X+iJY),
\qquad X,Y\in \mathbf R^{2d}.
\end{gathered}
\end{equation}

Then
$$
\mathcal V_{\psi_0} \mathfrak a(X, Y) = \pi^{-d}
e^{- |\kappa(X,Y)|^2} e^{i \sigma(Y, X)} (\mathfrak V_{\sigma, d} \mathfrak a)
\left( \kappa (X,Y)\right) . 
$$

\label{Prop:FrFTSymplSTFT}
Let $\psi _0$ be as in 
\eqref{Eq:SymplGaussWindow},
$\mathfrak a \in \mathcal S _{1/2}'(\mathbf R^{2d})$,
and let

\begin{equation}
\label{Eq:MatrixMDef}
M_{\rho,\theta}=\frac12
 \left (
 \begin{matrix}
 A_{\theta-\rho}+A_{\theta+\rho}
 &
 A_{\theta-\rho}-A_{\theta+\rho}
 \\
 A_{\theta-\rho}-A_{\theta+\rho}
 &
 A_{\theta-\rho}+A_{\theta+\rho}
 \end{matrix}
 \right ).
\end{equation}

Then

\begin{equation}
\label{Eq:FrFTSymplSTFT}
 |\mathcal V _{\psi_0}\mathscr F_{\sigma,(\rho,\theta)} \mathfrak a(X,Y)|
 =
 |(\mathcal V _{\psi_0}\mathfrak a)(M_{\rho,\theta}(X,Y))|.
\end{equation}

\label{Def:GenSymplModSpace}
Let $\mathscr B$ be a solid QBF space on $\mathbf R^{4d}$, 
$\omega \in\mathscr P _A(\mathbf R^{4d})$,
and let
$\psi _0$ be as in \eqref{Eq:SymplGaussWindow}. 
Then the \emph{symplectic modulation space}
$M_\sigma (\omega ,\mathscr B )$ consists
of all $\mathfrak a \in \mathcal H _{\sigma ,\flat _1}'(\mathbf R^{2d})$ such that

\begin{equation}
\label{Eq:GenSymplModNormDef}
\Vert \mathfrak a\Vert _{M_\sigma (\omega ,\mathscr B )}
\equiv \Vert \mathcal V _{\psi _0} \mathfrak a \cdot \omega \Vert _{\mathscr B}
\end{equation}

is finite.

\label{Def:FrSymplFTScales}
Let $\mathscr B$ be a solid QBF space on $\mathbf R^{4d}$, and let
$M_{\rho ,\theta}$ be as in \eqref{Eq:MatrixMDef}.
\begin{enumerate}
\item The space
$\mathscr B _{\sigma ,(\rho ,\theta )}$ is given by

\begin{equation}
\mathscr B _{\sigma ,(\rho ,\theta )}
\equiv
\{ \, H\in \mathcal M (\mathbf R^{4d})\, ;\, H(M_{\rho ,\theta } \, \cdot \,  )\in 
\mathscr B\, \} .
\end{equation}

The topology of $\mathscr B _{\sigma ,(\rho ,\theta )}$is given by the
quasi-norm

\begin{equation}
\Vert H\Vert _{\mathscr B _{\sigma ,(\rho ,\theta )}}
\equiv 
\Vert H(M_{\rho ,\theta } \, \cdot \,  )\Vert _{\mathscr B},
\qquad
H\in \mathscr B _{\sigma ,(\rho ,\theta )} .
\end{equation}


\vspace{0.1cm}

\item $\mathscr B$ is called \emph{symplectic phase rotational invariant},
if $\mathscr B _{\sigma ,(\rho ,\theta )} =\mathscr B$
and $\Vert H\Vert _{\mathscr B _{\sigma ,(\rho ,\theta )}}=\Vert H\Vert _{\mathscr B}$, for every
$\rho ,\theta \in \mathbf R^{d}$ and $H\in \mathscr B$.
\end{enumerate}
